/*Table structure for table `bill_paymongo` */

CREATE TABLE `bill_paymongo` (
  `bill_paymongo_pk` int(11) NOT NULL AUTO_INCREMENT,
  `id` varchar(100) NOT NULL,
  `event_type` varchar(100) DEFAULT NULL,
  `source_type` varchar(100) DEFAULT NULL,
  `amount` int(11) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `line1` varchar(500) DEFAULT NULL,
  `line2` varchar(500) DEFAULT NULL,
  `postal_code` varchar(100) DEFAULT NULL,
  `state` varchar(200) DEFAULT NULL,
  `email` varchar(200) DEFAULT NULL,
  `name` varchar(500) DEFAULT NULL,
  `phone` varchar(200) DEFAULT NULL,
  `currency` varchar(200) DEFAULT NULL,
  `livemode` tinyint(1) DEFAULT NULL,
  `checkout_url` varchar(999) DEFAULT NULL,
  `failed_url` varchar(999) DEFAULT NULL,
  `success_url` varchar(999) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  `type` varchar(100) DEFAULT NULL,
  `created_at` int(11) DEFAULT NULL,
  `updated_at` int(11) DEFAULT NULL,
  `paid_at` int(11) DEFAULT NULL,
  `consult_req_pk` varchar(20) NOT NULL,
  `fee` int(11) DEFAULT NULL,
  `pay_descrip` varchar(200) DEFAULT NULL,
  `pay_net_amount` int(11) DEFAULT NULL,
  `pay_payout` int(11) DEFAULT NULL,
  `pay_src_id` varchar(999) DEFAULT NULL,
  `pay_src_type` varchar(999) DEFAULT NULL,
  `pay_statement_descrip` varchar(200) DEFAULT NULL,
  `payment_intent_id` varchar(200) DEFAULT NULL,
  `origin` varchar(200) DEFAULT NULL,
  `tax_amount` varchar(200) DEFAULT NULL,
  `refunds` varchar(200) DEFAULT NULL,
  `taxes` varchar(200) DEFAULT NULL,
  `access_url` varchar(200) DEFAULT NULL,
  `client_key` varchar(999) DEFAULT NULL,
  `card_src_id` varchar(200) DEFAULT NULL,
  `card_src_type` varchar(200) DEFAULT NULL,
  `card_src_brand` varchar(200) DEFAULT NULL,
  `card_src_country` varchar(200) DEFAULT NULL,
  `card_src_last4` varchar(200) DEFAULT NULL,
  `logged_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`bill_paymongo_pk`,`id`)
