/*Table structure for table `def_val` */

CREATE TABLE `def_val` (
  `remarks` varchar(500) NOT NULL,
  `val` varchar(500) NOT NULL,
  `descrip` varchar(500) NOT NULL,
  `encoded_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`remarks`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

/*Data for the table `def_val` */

insert  into `def_val`(`remarks`,`val`,`descrip`,`encoded_at`) values ('hospital_address','Lanang Street, Davao City, Davao Del Sur, Philippines 8000','','2021-08-21 15:31:05'),('hospital_email','lpdhi@gmail.com','','2021-08-21 15:31:16'),('hospital_phone','+639299550278','','2021-08-21 15:30:39'),('hosp_initial','LPDHI','hospital initial','2021-08-21 15:30:39'),('hosp_name','Lanang Premiere Hospital, Inc','hospital name','2021-08-21 15:30:39');

/*Table structure for table `department` */

CREATE TABLE `department` (
  `dept_pk` int(11) NOT NULL AUTO_INCREMENT,
  `dept_code` varchar(20) NOT NULL,
  `dept_name` varchar(250) NOT NULL,
  `notes` text,
  `is_active` enum('y','n') NOT NULL,
  `encoded_at` datetime NOT NULL,
  `encoder_pk` varchar(20) NOT NULL,
  PRIMARY KEY (`dept_pk`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;

/*Data for the table `department` */

insert  into `department`(`dept_pk`,`dept_code`,`dept_name`,`notes`,`is_active`,`encoded_at`,`encoder_pk`) values (1,'D001','Surgery','Surgery Department','y','2021-08-11 17:22:29','54'),(2,'D002','Eye Center','Caters patients who have problem with their eyes!!!','y','2021-08-11 17:23:02','54');

/*Table structure for table `dept_resident` */

CREATE TABLE `dept_resident` (
  `dept_res_pk` int(11) NOT NULL AUTO_INCREMENT,
  `dept_pk` int(11) NOT NULL,
  `res_pk` int(11) NOT NULL,
  `notes` text,
  `is_active` enum('y','n') NOT NULL,
  `encoded_at` datetime NOT NULL,
  `encoder_pk` varchar(20) NOT NULL,
  PRIMARY KEY (`dept_res_pk`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;

/*Data for the table `dept_resident` */

insert  into `dept_resident`(`dept_res_pk`,`dept_pk`,`res_pk`,`notes`,`is_active`,`encoded_at`,`encoder_pk`) values (1,2,2,'-','y','2021-08-12 11:11:09','54'),(2,2,1,'','y','2021-08-12 11:18:01','54');

/*Table structure for table `docspecialtymaster` */

CREATE TABLE `docspecialtymaster` (
  `spclcode` char(3) NOT NULL DEFAULT '',
  `mainservice` varchar(150) DEFAULT '',
  `spcldesc` varchar(35) NOT NULL,
  `active` enum('Y','N') NOT NULL DEFAULT 'Y',
  `dateencoded` datetime NOT NULL,
  `encodedby` varchar(10) NOT NULL,
  `tssepcialty` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`spclcode`)
