  `email` varchar(200) NOT NULL,
  `mob_no` varchar(100) NOT NULL,
  `line1` varchar(300) NOT NULL,
  `line2` varchar(300) NOT NULL,
  `brgy_pk` varchar(20) NOT NULL,
