/* Function  structure for function  `getBrgyCityMun` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getBrgyCityMun`(brgyCode VARCHAR(20)) RETURNS varchar(20) CHARSET utf8
BEGIN
	DECLARE id VARCHAR(20);
	
	SET id = (SELECT citymuncode FROM `psgcaddress` WHERE `barangaycode`= brgyCode);
	
	RETURN id;
    END */$$
DELIMITER ;

/* Function  structure for function  `getBrgyProvince` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getBrgyProvince`(brgyCode varchar(20)) RETURNS varchar(20) CHARSET utf8
BEGIN
	declare id varchar(20);
	
	set id = (select provincecode from `psgcaddress` where `barangaycode`= brgyCode);
	
	return id;
    END */$$
DELIMITER ;

/* Function  structure for function  `getBrgyRegion` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getBrgyRegion`(brgyCode varchar(20)) RETURNS varchar(20) CHARSET utf8
BEGIN
	declare c  varchar(20);
	
	set c = (SELECT regioncode FROM `psgcaddress` WHERE `barangaycode` = brgyCode LIMIT 1);
	
	return c;
    END */$$
DELIMITER ;

/* Function  structure for function  `GetClientIdByDateNo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `GetClientIdByDateNo`(pDateno INTEGER(11)) RETURNS varchar(20) CHARSET utf8
BEGIN
	declare c  varchar(20);
	
	set c = (SELECT clinclientno FROM `clinicschedule` cs 
JOIN `clinicscheddates` csd ON cs.`schedno` = csd.`schedno` WHERE csd.`dateno` = pDateno);
	
	return c;
    END */$$
DELIMITER ;

/* Function  structure for function  `getUserClinicName` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getUserClinicName`(puserno int(11)) RETURNS varchar(255) CHARSET utf8
BEGIN
	return (SELECT `clinicname` FROM `users`  WHERE  userno=puserno limit 1);
    END */$$
DELIMITER ;

/* Function  structure for function  `getUserClinicNo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getUserClinicNo`(puserno int(11)) RETURNS int(11)
BEGIN
	RETURN (SELECT `clinicno` FROM `users`  WHERE  userno=puserno LIMIT 1);
    END */$$
DELIMITER ;

/* Function  structure for function  `getUserDoctorNo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getUserDoctorNo`(puserno int(11)) RETURNS int(11)
BEGIN
	RETURN (SELECT clindocno FROM clinicdoctor WHERE  userno=puserno LIMIT 1);
	
    END */$$
DELIMITER ;

/* Function  structure for function  `getUserFullnameByUserNo` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getUserFullnameByUserNo`(puserno int(11)) RETURNS varchar(255) CHARSET latin1
BEGIN
	return (SELECT fullname FROM users WHERE userno = puserno);
    END */$$
DELIMITER ;

/* Function  structure for function  `NextClinicId` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `NextClinicId`() RETURNS varchar(20) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(20);
	
	SET nxt = (SELECT COALESCE(CONCAT("C",LPAD(REPLACE(MAX(clncid),"C","")+1,8,"0")),'C00000001') FROM clinic);
	
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `NextMedId` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `NextMedId`() RETURNS varchar(20) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(20);
	
	SET nxt = (SELECT COALESCE(CONCAT("M",LPAD(REPLACE(MAX(medcode),"M","")+1,4,"0")),'M0001') FROM clinicmedicine);
	
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `NextPatientId` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `NextPatientId`() RETURNS varchar(20) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(20);
	
	SET nxt = (SELECT COALESCE(CONCAT("PAT",LPAD(REPLACE(MAX(clinpatno),"PAT","")+1,8,"0")),'PAT00000001') FROM clinicpatient);
	
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `NextProcId` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `NextProcId`() RETURNS varchar(20) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(20);
	
	SET nxt = (SELECT COALESCE(CONCAT("P",LPAD(REPLACE(MAX(proccode),"P","")+1,4,"0")),'P0001') FROM clinicprocedure);
	
	RETURN nxt;
    END */$$
DELIMITER ;

/* Function  structure for function  `next_consult_consult_req_pk` */

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `next_consult_consult_req_pk`(inc_val int(11)) RETURNS varchar(30) CHARSET latin1
BEGIN
	DECLARE nxt VARCHAR(30);
	
	SET nxt = (SELECT COALESCE(CONCAT(YEAR(NOW()),MONTH(NOW()),'R',LPAD((MAX(SUBSTR(consult_req_pk,LOCATE('R',consult_req_pk) + coalesce(inc_val,1)))+COALESCE(inc_val,1)),4,0) ), CONCAT(YEAR(NOW()),MONTH(NOW()),'R','0001'))  AS nxt    FROM `consult_request`);
	RETURN nxt;
    END */$$
DELIMITER ;

/*Table structure for table `psgcaddress` */

DROP TABLE IF EXISTS `psgcaddress`;

/*!50001 CREATE TABLE  `psgcaddress`(
 `regioncode` varchar(10) ,
 `regiondesc` varchar(100) ,
 `provincecode` varchar(10) ,
 `provincedesc` varchar(100) ,
 `citymuncode` varchar(10) ,
 `citymundesc` varchar(100) ,
 `barangaycode` varchar(10) ,
 `barangaydesc` varchar(100) ,
 `completeaddress` varchar(304) 
)*/;

/*View structure for view psgcaddress */

/*!50001 DROP TABLE IF EXISTS `psgcaddress` */;
/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`127.0.0.1` SQL SECURITY DEFINER VIEW `psgcaddress` AS select `p`.`regioncode` AS `regioncode`,`r`.`regiondesc` AS `regiondesc`,`c`.`provincecode` AS `provincecode`,`p`.`provincedesc` AS `provincedesc`,`b`.`citymuncode` AS `citymuncode`,`c`.`citymundesc` AS `citymundesc`,`b`.`barangaycode` AS `barangaycode`,`b`.`barangaydesc` AS `barangaydesc`,concat(`b`.`barangaydesc`,', ',`c`.`citymundesc`,', ',`p`.`provincedesc`) AS `completeaddress` from (((`barangay` `b` left join `citymunicipality` `c` on((`c`.`citymuncode` = `b`.`citymuncode`))) left join `province` `p` on((`p`.`provincecode` = `c`.`provincecode`))) left join `region` `r` on((`r`.`regioncode` = `p`.`regioncode`))) */;

